"use strict";
{ // primitive data type
    const country = "Bangladesh"; // string
    const number = 123; // number
    const isHappy = true; // boolean
    const x = undefined; // undefined
    const y = null; // null
    // non primitive data type
    const arr = ["John", "Smith", "Alice"]; // array
    const numbers = [1, 2, 3, 4, 5, 6]; //array
    const tuple = [1, "string", true]; // tuple
    // object
    const user = {
        company: "SoftyPy",
        firstName: "John",
        lastName: "Doe",
        isMarried: true,
    };
}
